SourceCode.Declaration:
/// <summary>
/// Extension class for MarkupTable
/// </summary>
[ExtensionOf(tablestr(MarkupTable))]
public final class AVAMarkupTableDbt_Extension
{
}

Method.Source:
/// <summary>
/// get text
/// </summary>
/// <param name="_markupModule">
/// module
/// </param>
/// <param name="_markupCode">
/// code
/// </param>
/// <param name="_languageId">
/// language
/// </param>
/// <returns>
/// text
/// </returns>
static FreeTxt AVATxt(MarkupModule       _markupModule,
                      MarkupCode          _markupCode,
                      LanguageId          _languageId = CompanyInfo::languageId())
{
    MarkupTable tblMarkupTable = MarkupTable::find(_markupModule,
                                                   _markupCode);
    LanguageTxt languageTxt = LanguageTxt::find(tblMarkupTable.TableId,
                                                   tblMarkupTable.RecId,
                                                   _languageId);

    return languageTxt.Txt ? languageTxt.Txt : tblMarkupTable.Txt;
}
